import hashlib,json,re
from html.parser import HTMLParser
from pathlib import Path
class ContactPage(HTMLParser):
    def __init__(self):
        super().__init__(); self.hidden=0; self.text=[]; self.fields=[]
    def handle_starttag(self,tag,attrs):
        if tag in ('script','style'): self.hidden+=1
        if tag in ('form','input','select','textarea','button'):
            attrs=dict(attrs)
            if attrs.get('type')!='hidden': self.fields.append({'tag':tag, **{key:attrs[key] for key in ('name','type','placeholder','aria-label') if key in attrs}})
    def handle_endtag(self,tag):
        if tag in ('script','style') and self.hidden: self.hidden-=1
    def handle_data(self,data):
        clean=' '.join(data.split())
        if clean and not self.hidden: self.text.append(clean)
